def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []

    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            above, below = r, h - r - 1
            candidates.append((min(above, below), -abs(above - below), "row", r))

    for c in range(w):
        if grid[0][c] != 0 and all(grid[i][c] == grid[0][c] for i in range(h)):
            left, right = c, w - c - 1
            candidates.append((min(left, right), -abs(left - right), "col", c))

    if not candidates:
        return [[0] * w for _ in range(h)]

    _, _, axis, sep = max(candidates)

    if axis == "row":
        n = min(sep, h - sep - 1)
        return [
            [2 if grid[i][j] != 0 and grid[sep + 1 + i][j] != 0 else 0
             for j in range(w)]
            for i in range(n)
        ]

    n = min(sep, w - sep - 1)
    return [
        [2 if grid[i][j] != 0 and grid[i][sep + 1 + j] != 0 else 0
         for j in range(n)]
        for i in range(h)
    ]
